-- Private bounded profile snapshot. All value columns belong to named domains.
CREATE TABLE editorial_import (singleton INTEGER PRIMARY KEY CHECK(singleton=1), actor TEXT NOT NULL, reason TEXT NOT NULL, imported_at TEXT NOT NULL) STRICT;
CREATE TABLE editorial_batch_source (ordinal INTEGER PRIMARY KEY, logical_path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, snapshot_sha256 TEXT NOT NULL, profile_count INTEGER NOT NULL) STRICT;
CREATE TABLE editorial_identity (person_id TEXT PRIMARY KEY NOT NULL) STRICT;
CREATE TABLE editorial_archive (logical_path TEXT PRIMARY KEY NOT NULL, sha256 TEXT NOT NULL, raw_bytes BLOB NOT NULL) STRICT;
CREATE TRIGGER editorial_archive_no_update BEFORE UPDATE ON editorial_archive BEGIN SELECT RAISE(ABORT,'immutable profile evidence'); END;
CREATE TRIGGER editorial_archive_no_delete BEFORE DELETE ON editorial_archive BEGIN SELECT RAISE(ABORT,'immutable profile evidence'); END;
CREATE TABLE editorial_batch (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "schema" TEXT, "status" TEXT, "visibility" TEXT, "lane" TEXT, "batch" TEXT, "approvalStatus" TEXT, "ratingPolicy" TEXT, "allocationPolicy" TEXT, "count" INTEGER, "profileCount" INTEGER, "contractPath" TEXT, "samplePath" TEXT, "soulAssignmentPath" TEXT) STRICT;
CREATE INDEX editorial_batch_parent ON editorial_batch(parent_key,ordinal);
CREATE TABLE editorial_profile (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "personId" TEXT, "name" TEXT, "status" TEXT, "soulRevisionRef" TEXT) STRICT;
CREATE INDEX editorial_profile_parent ON editorial_profile(parent_key,ordinal);
CREATE TABLE editorial_abilities (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL) STRICT;
CREATE INDEX editorial_abilities_parent ON editorial_abilities(parent_key,ordinal);
CREATE TABLE editorial_ability_value (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "base" INTEGER, "effective" INTEGER, "basis" TEXT) STRICT;
CREATE INDEX editorial_ability_value_parent ON editorial_ability_value(parent_key,ordinal);
CREATE TABLE editorial_skill (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "id" TEXT, "rating" REAL, "basis" TEXT) STRICT;
CREATE INDEX editorial_skill_parent ON editorial_skill(parent_key,ordinal);
CREATE TABLE editorial_skill_name (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ko" TEXT, "en" TEXT) STRICT;
CREATE INDEX editorial_skill_name_parent ON editorial_skill_name(parent_key,ordinal);
CREATE TABLE editorial_trait (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "id" TEXT, "basis" TEXT) STRICT;
CREATE INDEX editorial_trait_parent ON editorial_trait(parent_key,ordinal);
CREATE TABLE editorial_trait_name (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ko" TEXT, "en" TEXT) STRICT;
CREATE INDEX editorial_trait_name_parent ON editorial_trait_name(parent_key,ordinal);
CREATE TABLE editorial_trait_description (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ko" TEXT, "en" TEXT) STRICT;
CREATE INDEX editorial_trait_description_parent ON editorial_trait_description(parent_key,ordinal);
CREATE TABLE editorial_trait_behavior (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ko" TEXT, "en" TEXT) STRICT;
CREATE INDEX editorial_trait_behavior_parent ON editorial_trait_behavior(parent_key,ordinal);
CREATE TABLE editorial_trait_stress (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ko" TEXT, "en" TEXT) STRICT;
CREATE INDEX editorial_trait_stress_parent ON editorial_trait_stress(parent_key,ordinal);
CREATE TABLE editorial_trait_relationship (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ko" TEXT, "en" TEXT) STRICT;
CREATE INDEX editorial_trait_relationship_parent ON editorial_trait_relationship(parent_key,ordinal);
CREATE TABLE editorial_effect (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ability" TEXT, "delta" INTEGER) STRICT;
CREATE INDEX editorial_effect_parent ON editorial_effect(parent_key,ordinal);
CREATE TABLE editorial_narrative (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "ko" TEXT, "en" TEXT) STRICT;
CREATE INDEX editorial_narrative_parent ON editorial_narrative(parent_key,ordinal);
CREATE TABLE editorial_profile_evidence (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "path" TEXT, "anchor" TEXT, "quote" TEXT) STRICT;
CREATE INDEX editorial_profile_evidence_parent ON editorial_profile_evidence(parent_key,ordinal);
CREATE TABLE editorial_soul (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "id" TEXT, "name" TEXT, "period" TEXT, "sourceKind" TEXT, "interpretation" TEXT) STRICT;
CREATE INDEX editorial_soul_parent ON editorial_soul(parent_key,ordinal);
CREATE TABLE editorial_health (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "status" TEXT) STRICT;
CREATE INDEX editorial_health_parent ON editorial_health(parent_key,ordinal);
CREATE TABLE editorial_body_part (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "id" TEXT, "severity" TEXT CHECK("severity" IS NULL), "function" TEXT CHECK("function" IS NULL)) STRICT;
CREATE INDEX editorial_body_part_parent ON editorial_body_part(parent_key,ordinal);
CREATE TABLE editorial_disease (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL) STRICT;
CREATE INDEX editorial_disease_parent ON editorial_disease(parent_key,ordinal);
CREATE TABLE editorial_batch_source_path (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "value" TEXT) STRICT;
CREATE INDEX editorial_batch_source_path_parent ON editorial_batch_source_path(parent_key,ordinal);
CREATE TABLE editorial_batch_source_ref (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "value" TEXT) STRICT;
CREATE INDEX editorial_batch_source_ref_parent ON editorial_batch_source_ref(parent_key,ordinal);
CREATE TABLE editorial_batch_source_card (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "value" TEXT) STRICT;
CREATE INDEX editorial_batch_source_card_parent ON editorial_batch_source_card(parent_key,ordinal);
CREATE TABLE editorial_batch_limitation (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "value" TEXT) STRICT;
CREATE INDEX editorial_batch_limitation_parent ON editorial_batch_limitation(parent_key,ordinal);
CREATE TABLE editorial_profile_limitation (row_key TEXT PRIMARY KEY NOT NULL, parent_key TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), field_order TEXT NOT NULL, "value" TEXT) STRICT;
CREATE INDEX editorial_profile_limitation_parent ON editorial_profile_limitation(parent_key,ordinal);
